queries.sql:
DECLARE  @userId int = @p_userId;
DECLARE @startDate datetime = @p_startDate;

select t.Name, count(*)
from Posts p join PostTypes t on p.PostTypeId = t.Id
where OwnerUserId = @userId
and CreationDate >= @startDate
group by t.Name;

