queries.sql:
DECLARE  @UserId int = 103167;

select COUNT(myAnswer.ParentId) as NumQuestionsAnswerOffered
  from Posts as myAnswer
  left join Posts as theQuestion on theQuestion.Id = myAnswer.ParentId
  where myAnswer.ownerUserId = @UserId and myAnswer.postTypeId = 2 and myAnswer.CreationDate > {d '2013-02-01'}
  and myAnswer.Id = theQuestion.AcceptedAnswerId
;

