queries.sql:
SELECT  distinct *
from (
  SELECT count(*) as dups, 
   RelatedPostId as [Post Link]

  from PostLinks
   join Posts q on q.Id=RelatedPostId

  where LinkTypeId=3
  group by RelatedPostId

) d
where dups > @numdupes;

