queries.sql:
DECLARE  @user INT = @uid

IF ( (SELECT TOP 1 DATEDIFF(MONTH,GETDATE(),p.CreationDate) AS 'Date'
      FROM Posts p WHERE p.OwnerUserId = @user ORDER BY 'Date' DESC) < -12)
    SELECT 'No';
ELSE
    SELECT 'Yes';

